const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1) Geometry & Time
    const datePrimary = {start: '2025-09-13', end: '2025-09-14'};
    const firePt = ee.Geometry.Point([-118.9, 48.95]); // Lynx Mountain vicinity (NE Washington)
    const buf = firePt.buffer(90000); // 90 km buffer to span the border
    const bounds = buf.bounds();
    const coords = ee.List(ee.List(bounds.coordinates()).get(0));
    const ll = ee.List(coords.get(0)); // [minLon, minLat]
    const ur = ee.List(coords.get(2)); // [maxLon, maxLat]
    const minLon = ee.Number(ll.get(0));
    const minLat = ee.Number(ll.get(1));
    const maxLon = ee.Number(ur.get(0));
    const maxLat = ee.Number(ur.get(1));
    const latBorder = 49.0;
    const bcRect = ee.Geometry.Rectangle([minLon, latBorder, maxLon, maxLat], null, false);
    const waRect = ee.Geometry.Rectangle([minLon, minLat, maxLon, latBorder], null, false);
    const bcArea = bcRect.intersection(buf, ee.ErrorMargin(1));
    const waArea = waRect.intersection(buf, ee.ErrorMargin(1));
    const studyRegion = bcArea.union(waArea, ee.ErrorMargin(1));

    // Helpers
    const evalEE = (obj) => new Promise((res, rej) => obj.evaluate((v, e) => e ? rej(e) : res(v)));
    async function tryCollection(id, start, end, region) {
      const col = ee.ImageCollection(id)
        .filterDate(start, end)
        .filterBounds(region)
        .select(['absorbing_aerosol_index', 'qa_value']);
      const n = await evalEE(col.size());
      return {col, n, id, start, end};
    }

    // 2) Data Acquisition with fallback
    const attempts = [
      {id: 'COPERNICUS/S5P/OFFL/L3_AER_AI', start: datePrimary.start, end: datePrimary.end},
      {id: 'COPERNICUS/S5P/NRTI/L3_AER_AI', start: datePrimary.start, end: datePrimary.end},
      {id: 'COPERNICUS/S5P/OFFL/L3_AER_AI', start: '2025-09-12', end: '2025-09-14'},
      {id: 'COPERNICUS/S5P/NRTI/L3_AER_AI', start: '2025-09-12', end: '2025-09-14'}
    ];
    let chosen = null;
    for (const a of attempts) {
      const res = await tryCollection(a.id, a.start, a.end, studyRegion);
      if (res.n > 0) { chosen = res; break; }
    }
    if (!chosen) {
      console.log('S5P Images: 0');
      console.log('No images for date/region after fallbacks.');
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }
    console.log(`Dataset: ${chosen.id}`);
    console.log(`Date window: ${chosen.start} to ${chosen.end} | Images: ${chosen.n}`);

    // 3) Processing (mask QA)
    const masked = chosen.col.map(function(img) {
      const qa = img.select('qa_value');
      const aai = img.select('absorbing_aerosol_index');
      return aai.updateMask(qa.gte(0.5));
    });
    const aaiImg = masked.median();

    // 4) Stats
    const reducers = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    const bcDict = await evalEE(aaiImg.reduceRegion({
      reducer: reducers, geometry: bcArea, scale: 7000, maxPixels: 1e9
    }));
    const waDict = await evalEE(aaiImg.reduceRegion({
      reducer: reducers, geometry: waArea, scale: 7000, maxPixels: 1e9
    }));
    const bcMean = bcDict ? bcDict.absorbing_aerosol_index_mean : null;
    const bcCount = bcDict ? bcDict.absorbing_aerosol_index_count : 0;
    const waMean = waDict ? waDict.absorbing_aerosol_index_mean : null;
    const waCount = waDict ? waDict.absorbing_aerosol_index_count : 0;

    // 5) Validation
    if ((bcCount || 0) === 0 || (waCount || 0) === 0) {
      console.log(`BC Pixels: ${bcCount || 0}, WA Pixels: ${waCount || 0}`);
      console.log('No valid pixels after QA masking in one or both areas.');
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }
    if (bcMean === null || waMean === null || !isFinite(bcMean) || !isFinite(waMean)) {
      console.log(`BC Mean AAI: ${bcMean}, WA Mean AAI: ${waMean}`);
      console.log('C3: Calculation Failure (Result invalid).');
      console.log('C3');
      return;
    }

    // 6) Decision
    const thr = 1.0; // AAI threshold indicative of smoke aerosols
    console.log(`BC Pixels: ${bcCount}, Mean AAI: ${bcMean.toFixed(2)}`);
    console.log(`WA Pixels: ${waCount}, Mean AAI: ${waMean.toFixed(2)}`);
    console.log(`Threshold (AAI): ${thr.toFixed(1)}`);
    const yes = (bcMean >= thr) && (waMean >= thr);

    console.log(yes ? 'A: Yes' : 'B: No');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
